import type { Request, Response } from "express";

import { ENV } from "../env.server";

export const SESSION_COOKIE = ENV.SESSION_COOKIE_NAME;

const isProd = ENV.NODE_ENV === "production";

function parseCookies(header: string | undefined): Record<string, string> {
	const out: Record<string, string> = {};
	if (!header) return out;
	for (const part of header.split(";")) {
		const idx = part.indexOf("=");
		if (idx === -1) continue;
		const key = part.slice(0, idx).trim();
		if (!key) continue;
		out[key] = decodeURIComponent(part.slice(idx + 1).trim());
	}
	return out;
}

export function getSessionCookie(req: Request): string | undefined {
	return parseCookies(req.headers.cookie)[SESSION_COOKIE];
}

export function setSessionCookie(
	res: Response,
	token: string,
	expiresAt: Date,
): void {
	res.cookie(SESSION_COOKIE, token, {
		httpOnly: true,
		sameSite: "lax",
		secure: isProd,
		path: "/",
		expires: expiresAt,
	});
}

export function clearSessionCookie(res: Response): void {
	res.clearCookie(SESSION_COOKIE, {
		httpOnly: true,
		sameSite: "lax",
		secure: isProd,
		path: "/",
	});
}

import type { Database } from "@cube/db";
import { projects } from "@cube/db";
import { eq } from "drizzle-orm";
import type { NextFunction, Request, Response } from "express";

import { db } from "../services";
import type { VerifiedApiKey } from "./apiKeys";
import { verifyApiKey } from "./apiKeys";
import { getSessionCookie } from "./cookies";
import type { SessionUser } from "./sessions";
import { resolveSession } from "./sessions";

export type AuthContext =
	| { kind: "session"; user: SessionUser; sessionId: string }
	| { kind: "apiKey"; key: VerifiedApiKey };

export function getAuth(res: Response): AuthContext | undefined {
	return (res.locals as { auth?: AuthContext }).auth;
}

/** Extract a machine credential from `Authorization: Bearer` or `x-api-key`. */
function machineCredential(req: Request): string | undefined {
	const header = req.header("authorization");
	if (header?.toLowerCase().startsWith("bearer ")) {
		return header.slice(7).trim();
	}
	return req.header("x-api-key") ?? undefined;
}

async function resolveAuthContext(
	database: Database,
	req: Request,
): Promise<AuthContext | undefined> {
	const session = await resolveSession(database, getSessionCookie(req));
	if (session) {
		return {
			kind: "session",
			user: session.user,
			sessionId: session.sessionId,
		};
	}
	const key = await verifyApiKey(database, machineCredential(req));
	if (key) return { kind: "apiKey", key };
	return undefined;
}

async function attach(
	database: Database,
	req: Request,
	res: Response,
): Promise<AuthContext | undefined> {
	const auth = await resolveAuthContext(database, req);
	if (auth) (res.locals as { auth?: AuthContext }).auth = auth;
	return auth;
}

/** Accepts either a dashboard session or a project API key. */
export function requireAuth(_database: Database = db) {
	return async (req: Request, res: Response, next: NextFunction) => {
		const auth = await attach(_database, req, res);
		if (!auth) {
			res.status(401).json({ error: "authentication required" });
			return;
		}
		next();
	};
}

/** Dashboard-only: a valid user session. */
export function requireSession(database: Database = db) {
	return async (req: Request, res: Response, next: NextFunction) => {
		const auth = await resolveAuthContext(database, req);
		if (!auth || auth.kind !== "session") {
			res.status(401).json({ error: "session required" });
			return;
		}
		(res.locals as { auth?: AuthContext }).auth = auth;
		next();
	};
}

/** Machine-only: a valid project API key. */
export function requireApiKey(database: Database = db) {
	return async (req: Request, res: Response, next: NextFunction) => {
		const auth = await resolveAuthContext(database, req);
		if (!auth || auth.kind !== "apiKey") {
			res.status(401).json({ error: "API key required" });
			return;
		}
		(res.locals as { auth?: AuthContext }).auth = auth;
		next();
	};
}

/**
 * Project ids the caller may see. A session sees every project it owns; an API
 * key sees exactly its own project.
 */
export async function accessibleProjectIds(
	database: Database,
	auth: AuthContext,
): Promise<string[]> {
	if (auth.kind === "apiKey") return [auth.key.projectId];
	const rows = await database
		.select({ id: projects.id })
		.from(projects)
		.where(eq(projects.userId, auth.user.id));
	return rows.map((row) => row.id);
}

/**
 * Tiny in-process sliding-window limiter. Good enough to blunt credential
 * stuffing on a single instance; swap for Redis when running more than one.
 */
type Bucket = { count: number; resetAt: number };

const buckets = new Map<string, Bucket>();
const MAX_BUCKETS = 10_000;

export type RateLimitResult = { allowed: boolean; retryAfterMs: number };

export function checkRateLimit(
	key: string,
	options: { max: number; windowMs: number },
): RateLimitResult {
	const now = Date.now();

	if (buckets.size > MAX_BUCKETS) {
		for (const [k, bucket] of buckets) {
			if (bucket.resetAt <= now) buckets.delete(k);
		}
	}

	const bucket = buckets.get(key);
	if (!bucket || bucket.resetAt <= now) {
		buckets.set(key, { count: 1, resetAt: now + options.windowMs });
		return { allowed: true, retryAfterMs: 0 };
	}

	if (bucket.count >= options.max) {
		return { allowed: false, retryAfterMs: bucket.resetAt - now };
	}

	bucket.count += 1;
	return { allowed: true, retryAfterMs: 0 };
}

export function resetRateLimit(key: string): void {
	buckets.delete(key);
}

import { users } from "@cube/db";
import { eq, or } from "drizzle-orm";
import { Router } from "express";

import { clearSessionCookie, getSessionCookie, setSessionCookie } from "../auth/cookies";
import { getAuth, requireSession } from "../auth/middleware";
import { hashPassword, verifyPassword } from "../auth/password";
import { checkRateLimit, resetRateLimit } from "../auth/rateLimit";
import { createSession, revokeSession } from "../auth/sessions";
import { ENV } from "../env.server";
import { db } from "../services";
import { loadProjects } from "./projects";

export const authRouter = Router();

// A hash to verify against when the user does not exist, so login latency does
// not reveal whether an account is registered.
const DUMMY_HASH = await hashPassword("cube-dummy-password");

function stringField(value: unknown): string | undefined {
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

authRouter.post("/login", async (req, res) => {
	const body = (req.body ?? {}) as Record<string, unknown>;
	const identifier =
		stringField(body.email) ?? stringField(body.username) ?? "";
	const password = typeof body.password === "string" ? body.password : "";

	if (!identifier || !password) {
		res.status(400).json({ error: "email and password are required" });
		return;
	}

	const ip = req.ip ?? "unknown";
	const limitKey = `login:${ip}:${identifier.toLowerCase()}`;
	const limit = checkRateLimit(limitKey, {
		max: ENV.AUTH_LOGIN_MAX_ATTEMPTS,
		windowMs: ENV.AUTH_LOGIN_WINDOW_MINUTES * 60_000,
	});
	if (!limit.allowed) {
		res.setHeader("Retry-After", Math.ceil(limit.retryAfterMs / 1000));
		res.status(429).json({ error: "too many attempts, try again later" });
		return;
	}

	const [user] = await db
		.select()
		.from(users)
		.where(
			or(
				eq(users.email, identifier.toLowerCase()),
				eq(users.username, identifier),
			),
		)
		.limit(1);

	const valid = await verifyPassword(password, user?.passwordHash ?? DUMMY_HASH);
	if (!user || !valid) {
		res.status(401).json({ error: "invalid credentials" });
		return;
	}

	resetRateLimit(limitKey);

	const { token, expiresAt } = await createSession(db, {
		userId: user.id,
		ttlDays: ENV.SESSION_TTL_DAYS,
		userAgent: req.header("user-agent") ?? null,
		ip,
	});
	setSessionCookie(res, token, expiresAt);

	res.json({
		user: { id: user.id, username: user.username, email: user.email },
		expiresAt: expiresAt.toISOString(),
	});
});

authRouter.post("/logout", async (req, res) => {
	await revokeSession(db, getSessionCookie(req));
	clearSessionCookie(res);
	res.status(204).end();
});

authRouter.get("/me", requireSession(), async (_req, res) => {
	const auth = getAuth(res);
	if (!auth || auth.kind !== "session") {
		res.status(401).json({ error: "session required" });
		return;
	}
	const projectList = await loadProjects(db, auth.user.id);
	res.json({ user: auth.user, projects: projectList });
});

import type { Database } from "@cube/db";
import { projects } from "@cube/db";
import { desc, eq } from "drizzle-orm";
import { Router } from "express";

import { getAuth, requireSession } from "../auth/middleware";
import { db } from "../services";

export type ProjectSummary = {
	id: string;
	name: string;
	slug: string;
	description: string | null;
	defaultCurrency: string;
};

export async function loadProjects(
	database: Database,
	userId: string,
): Promise<ProjectSummary[]> {
	return database
		.select({
			id: projects.id,
			name: projects.name,
			slug: projects.slug,
			description: projects.description,
			defaultCurrency: projects.defaultCurrency,
		})
		.from(projects)
		.where(eq(projects.userId, userId))
		.orderBy(desc(projects.createdAt));
}

export const projectsRouter = Router();

projectsRouter.get("/", requireSession(), async (_req, res) => {
	const auth = getAuth(res);
	if (!auth || auth.kind !== "session") {
		res.status(401).json({ error: "session required" });
		return;
	}
	res.json({ projects: await loadProjects(db, auth.user.id) });
});

import { apiKeys, projects } from "@cube/db";
import { and, desc, eq, inArray } from "drizzle-orm";
import { Router } from "express";

import { generateApiKey } from "../auth/apiKeys";
import { getAuth, requireSession } from "../auth/middleware";
import { db } from "../services";

export const apiKeysRouter = Router();

apiKeysRouter.use(requireSession());

async function ownedProjectIds(userId: string): Promise<string[]> {
	const rows = await db
		.select({ id: projects.id })
		.from(projects)
		.where(eq(projects.userId, userId));
	return rows.map((row) => row.id);
}

apiKeysRouter.get("/", async (_req, res) => {
	const auth = getAuth(res);
	if (!auth || auth.kind !== "session") {
		res.status(401).json({ error: "session required" });
		return;
	}
	const projectIds = await ownedProjectIds(auth.user.id);
	if (projectIds.length === 0) {
		res.json({ apiKeys: [] });
		return;
	}
	const rows = await db
		.select({
			id: apiKeys.id,
			name: apiKeys.name,
			keyPrefix: apiKeys.keyPrefix,
			projectId: apiKeys.projectId,
			projectName: projects.name,
			lastUsedAt: apiKeys.lastUsedAt,
			expiresAt: apiKeys.expiresAt,
			revokedAt: apiKeys.revokedAt,
			createdAt: apiKeys.createdAt,
		})
		.from(apiKeys)
		.innerJoin(projects, eq(projects.id, apiKeys.projectId))
		.where(inArray(apiKeys.projectId, projectIds))
		.orderBy(desc(apiKeys.createdAt));
	res.json({ apiKeys: rows });
});

apiKeysRouter.post("/", async (req, res) => {
	const auth = getAuth(res);
	if (!auth || auth.kind !== "session") {
		res.status(401).json({ error: "session required" });
		return;
	}

	const body = (req.body ?? {}) as Record<string, unknown>;
	const projectId = typeof body.projectId === "string" ? body.projectId : "";
	if (!projectId) {
		res.status(400).json({ error: "projectId is required" });
		return;
	}

	const projectIds = await ownedProjectIds(auth.user.id);
	if (!projectIds.includes(projectId)) {
		res.status(404).json({ error: "project not found" });
		return;
	}

	const name =
		typeof body.name === "string" && body.name.trim()
			? body.name.trim()
			: `API key (${new Date().toISOString().slice(0, 10)})`;

	let expiresAt: Date | null = null;
	if (typeof body.expiresAt === "string" && body.expiresAt) {
		const parsed = new Date(body.expiresAt);
		if (Number.isNaN(parsed.getTime())) {
			res.status(400).json({ error: "expiresAt is not a valid date" });
			return;
		}
		expiresAt = parsed;
	}

	const { raw, keyPrefix, keyHash } = generateApiKey();
	const [created] = await db
		.insert(apiKeys)
		.values({ projectId, name, keyPrefix, keyHash, expiresAt })
		.returning({ id: apiKeys.id, createdAt: apiKeys.createdAt });

	// The raw key is returned exactly once; only its hash is stored.
	res.status(201).json({
		apiKey: {
			id: created?.id,
			name,
			keyPrefix,
			projectId,
			expiresAt,
			createdAt: created?.createdAt,
		},
		secret: raw,
	});
});

apiKeysRouter.delete("/:id", async (req, res) => {
	const auth = getAuth(res);
	if (!auth || auth.kind !== "session") {
		res.status(401).json({ error: "session required" });
		return;
	}
	const id = typeof req.params.id === "string" ? req.params.id : "";
	const projectIds = await ownedProjectIds(auth.user.id);
	if (projectIds.length === 0) {
		res.status(404).json({ error: "API key not found" });
		return;
	}

	const revoked = await db
		.update(apiKeys)
		.set({ revokedAt: new Date() })
		.where(
			and(eq(apiKeys.id, id), inArray(apiKeys.projectId, projectIds)),
		)
		.returning({ id: apiKeys.id });

	if (revoked.length === 0) {
		res.status(404).json({ error: "API key not found" });
		return;
	}
	res.status(204).end();
});

import { ApprovalError, decideEmail } from "@cube/agent";
import {
	agentRuns,
	auditLog,
	causes,
	customers,
	emailActions,
	failedPaymentEvents,
	investigations,
	mitigationScenarios,
	recommendations,
} from "@cube/db";
import { and, desc, eq, inArray } from "drizzle-orm";
import type { Request, Response } from "express";
import { Router } from "express";

import { accessibleProjectIds, getAuth, requireAuth } from "../auth/middleware";
import { agentConfig } from "../config";
import { db } from "../services";

export const investigationsRouter = Router();

const uuidPattern =
	/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Every route below is scoped to the caller's projects (all owned projects for
// a dashboard session, or the single project of an API key).
investigationsRouter.use(requireAuth());

async function callerProjectIds(res: Response): Promise<string[]> {
	const auth = getAuth(res);
	if (!auth) return [];
	return accessibleProjectIds(db, auth);
}

/** True only if the investigation's customer belongs to an allowed project. */
async function investigationInScope(
	id: string,
	projectIds: string[],
): Promise<boolean> {
	if (projectIds.length === 0) return false;
	const [row] = await db
		.select({ projectId: customers.projectId })
		.from(investigations)
		.innerJoin(customers, eq(customers.id, investigations.customerId))
		.where(eq(investigations.id, id))
		.limit(1);
	return Boolean(row && projectIds.includes(row.projectId));
}

/** Shared handler for the human-in-the-loop email approval endpoints. */
async function decide(
	req: Request,
	res: Response,
	decision: "approved" | "rejected",
): Promise<void> {
	const id = typeof req.params.id === "string" ? req.params.id : "";
	if (!id || !uuidPattern.test(id)) {
		res.status(404).json({ error: "investigation not found" });
		return;
	}

	const projectIds = await callerProjectIds(res);
	if (!(await investigationInScope(id, projectIds))) {
		res.status(404).json({ error: "investigation not found" });
		return;
	}

	const body = (req.body ?? {}) as { actor?: unknown; reason?: unknown };
	try {
		const outcome = await decideEmail(db, agentConfig, {
			investigationId: id,
			decision,
			actor: typeof body.actor === "string" ? body.actor : undefined,
			reason: typeof body.reason === "string" ? body.reason : undefined,
		});
		res.json(outcome);
	} catch (error) {
		if (error instanceof ApprovalError) {
			res.status(409).json({ error: error.message });
			return;
		}
		throw error;
	}
}

investigationsRouter.post("/:id/approve", (req, res) =>
	decide(req, res, "approved"),
);

investigationsRouter.post("/:id/reject", (req, res) =>
	decide(req, res, "rejected"),
);

investigationsRouter.get("/summary", async (_req, res) => {
	const projectIds = await callerProjectIds(res);
	if (projectIds.length === 0) {
		res.json({
			total: 0,
			byStatus: {},
			revenueAtRiskCents: 0,
			emailsSent: 0,
			emailsBlocked: 0,
		});
		return;
	}

	const rows = await db
		.select({
			status: investigations.status,
			revenueAtRiskCents: investigations.revenueAtRiskCents,
		})
		.from(investigations)
		.innerJoin(customers, eq(customers.id, investigations.customerId))
		.where(inArray(customers.projectId, projectIds));

	const byStatus: Record<string, number> = {};
	let revenueAtRiskCents = 0;
	for (const row of rows) {
		byStatus[row.status] = (byStatus[row.status] ?? 0) + 1;
		revenueAtRiskCents += row.revenueAtRiskCents ?? 0;
	}

	const emails = await db
		.select({ status: emailActions.status })
		.from(emailActions)
		.innerJoin(
			investigations,
			eq(investigations.id, emailActions.investigationId),
		)
		.innerJoin(customers, eq(customers.id, investigations.customerId))
		.where(inArray(customers.projectId, projectIds));
	const emailsSent = emails.filter((e) => e.status === "sent").length;
	const emailsBlocked = emails.filter((e) => e.status === "blocked").length;

	res.json({
		total: rows.length,
		byStatus,
		revenueAtRiskCents,
		emailsSent,
		emailsBlocked,
	});
});

investigationsRouter.get("/", async (_req, res) => {
	const projectIds = await callerProjectIds(res);
	if (projectIds.length === 0) {
		res.json({ investigations: [] });
		return;
	}

	const rows = await db
		.select({
			id: investigations.id,
			status: investigations.status,
			createdAt: investigations.createdAt,
			customerName: customers.name,
			customerEmail: customers.email,
			amountCents: failedPaymentEvents.amountCents,
			currency: failedPaymentEvents.currency,
			declineCode: failedPaymentEvents.declineCode,
			causeCode: causes.code,
			confidence: causes.confidence,
			severity: causes.severity,
			revenueAtRiskCents: investigations.revenueAtRiskCents,
			neatlogsTraceId: investigations.neatlogsTraceId,
			cfoScenarioRef: investigations.cfoScenarioRef,
		})
		.from(investigations)
		.innerJoin(customers, eq(customers.id, investigations.customerId))
		.innerJoin(
			failedPaymentEvents,
			eq(failedPaymentEvents.id, investigations.eventId),
		)
		.leftJoin(causes, eq(causes.investigationId, investigations.id))
		.where(inArray(customers.projectId, projectIds))
		.orderBy(desc(investigations.createdAt))
		.limit(100);

	res.json({ investigations: rows });
});

investigationsRouter.get("/:id", async (req, res) => {
	const id = typeof req.params.id === "string" ? req.params.id : "";
	if (!id || !uuidPattern.test(id)) {
		res.status(404).json({ error: "investigation not found" });
		return;
	}

	const projectIds = await callerProjectIds(res);
	const [row] = await db
		.select({
			investigation: investigations,
			customer: customers,
			event: failedPaymentEvents,
		})
		.from(investigations)
		.innerJoin(customers, eq(customers.id, investigations.customerId))
		.innerJoin(
			failedPaymentEvents,
			eq(failedPaymentEvents.id, investigations.eventId),
		)
		.where(
			and(
				eq(investigations.id, id),
				inArray(customers.projectId, projectIds.length ? projectIds : [""]),
			),
		)
		.limit(1);

	if (!row) {
		res.status(404).json({ error: "investigation not found" });
		return;
	}

	const [cause] = await db
		.select()
		.from(causes)
		.where(eq(causes.investigationId, id))
		.limit(1);
	const [recommendation] = await db
		.select()
		.from(recommendations)
		.where(eq(recommendations.investigationId, id))
		.limit(1);
	const scenarios = await db
		.select()
		.from(mitigationScenarios)
		.where(eq(mitigationScenarios.investigationId, id));
	const emails = await db
		.select()
		.from(emailActions)
		.where(eq(emailActions.investigationId, id));
	const timeline = await db
		.select()
		.from(auditLog)
		.where(eq(auditLog.entityId, id))
		.orderBy(auditLog.at);
	const runs = await db
		.select()
		.from(agentRuns)
		.where(eq(agentRuns.investigationId, id));

	res.json({
		...row,
		cause: cause ?? null,
		recommendation: recommendation ?? null,
		scenarios,
		emails,
		timeline,
		runs,
	});
});

