import {
	ApiError,
	createApiKey,
	getWebhookSecret,
	revokeApiKey,
	rotateWebhookSecret,
} from "@/lib/api-client";
import type { ApiKey, Project } from "@/lib/types";

export function ApiKeyManager({
	projects,
	apiKeys,
}: {
	projects: Project[];
	apiKeys: ApiKey[];
}) {
	const router = useRouter();
	const [projectId, setProjectId] = useState(projects[0]?.id ?? "");
	const [name, setName] = useState("");
	const [pending, setPending] = useState(false);
	const [newSecret, setNewSecret] = useState<{
		name: string;
		secret: string;
	} | null>(null);
	const [webhook, setWebhook] = useState<
		Record<string, { url: string; secret: string | null }>
	>({});

	function handleError(error: unknown): void {
		if (error instanceof ApiError && error.status === 401) {
			router.replace("/login");
			return;
		}
		toast.error(error instanceof Error ? error.message : "action failed");
	}

	async function onCreate(event: React.FormEvent<HTMLFormElement>) {
		event.preventDefault();
		if (!projectId) return;
		setPending(true);
		setNewSecret(null);
		try {
			const created = await createApiKey(
				projectId,
				name.trim() || "API key",
			);
			setNewSecret({ name: created.apiKey.name, secret: created.secret });
			setName("");
			toast.success("API key created");
			router.refresh();
		} catch (error) {
			handleError(error);
		} finally {
			setPending(false);
		}
	}

	async function onRevoke(id: string) {
		try {
			await revokeApiKey(id);
			toast.success("API key revoked");
			router.refresh();
		} catch (error) {
			handleError(error);
		}
	}

	async function onReveal(project: Project) {
		try {
			const data = await getWebhookSecret(project.id);
			setWebhook((prev) => ({
				...prev,
				[project.id]: { url: data.webhookUrl, secret: data.webhookSecret },
			}));
		} catch (error) {
			handleError(error);
		}
	}

	async function onRotate(project: Project) {
		try {
			const data = await rotateWebhookSecret(project.id);
			setWebhook((prev) => ({
				...prev,
				[project.id]: { url: data.webhookUrl, secret: data.webhookSecret },
			}));
			toast.success("Webhook secret rotated");
		} catch (error) {
			handleError(error);
		}
	}

